/**
 * Назначение: объявления типов для статических ассетов, импортируемых в TS.
 *
 * Функции:
 * - позволяет импортировать PNG как модуль (Metro возвращает идентификатор
 *   ассета числом).
 *
 * Слой: types (/src/types). Только декларации, без кода.
 */

declare module '*.png' {
  const asset: number;
  export default asset;
}
